import{_ as t,C as i,o as d,c as r,j as a,a as l,E as s,ag as n}from"./chunks/framework.CEtICT8r.js";const k=JSON.parse('{"title":"❓ 安装与常见问题","description":"","frontmatter":{"aside":false},"headers":[],"relativePath":"oj-extractor/faq.md","filePath":"oj-extractor/faq.md","lastUpdated":null}'),c={name:"oj-extractor/faq.md"};function h(p,e,u,q,b,g){const o=i("BackLink");return d(),r("div",null,[e[0]||(e[0]=a("h1",{id:"❓-安装与常见问题",tabindex:"-1"},[l("❓ 安装与常见问题 "),a("a",{class:"header-anchor",href:"#❓-安装与常见问题","aria-label":'Permalink to "❓ 安装与常见问题"'},"​")],-1)),s(o,{to:"/oj-extractor/",label:"返回工具详情"}),e[1]||(e[1]=n('<h2 id="q1-点击扩展图标没反应" tabindex="-1">Q1：点击扩展图标没反应？ <a class="header-anchor" href="#q1-点击扩展图标没反应" aria-label="Permalink to &quot;Q1：点击扩展图标没反应？&quot;">​</a></h2><ul><li>检查 VSCode 右下角是否有「OJ服务器已启动」通知。</li><li>如果没有，重启 VSCode。</li><li>仍不行？在 VSCode 中按 <code>Ctrl+Shift+P</code> → 输入 <code>OJ</code>，查看扩展命令是否正常。</li></ul><h2 id="q2-提示端口-8765-被占用" tabindex="-1">Q2：提示端口 8765 被占用？ <a class="header-anchor" href="#q2-提示端口-8765-被占用" aria-label="Permalink to &quot;Q2：提示端口 8765 被占用？&quot;">​</a></h2><p>说明你开了多个 VSCode 窗口。关掉多余的窗口，只留一个即可（多窗口时只有第一个能启动服务器，不影响使用）。</p><h2 id="q3-支持其他-oj-吗" tabindex="-1">Q3：支持其他 OJ 吗？ <a class="header-anchor" href="#q3-支持其他-oj-吗" aria-label="Permalink to &quot;Q3：支持其他 OJ 吗？&quot;">​</a></h2><p>目前只适配了 <strong>实验舱 OJ</strong>。其他 OJ 平台的 API 结构和字段名不同，需要修改代码才能支持。</p><h2 id="q4-edge-重启后第一次点击没反应" tabindex="-1">Q4：Edge 重启后第一次点击没反应？ <a class="header-anchor" href="#q4-edge-重启后第一次点击没反应" aria-label="Permalink to &quot;Q4：Edge 重启后第一次点击没反应？&quot;">​</a></h2><p>浏览器会话重启后缓存会被清空。<strong>刷新一次题目页面</strong>再点图标即可。</p><h2 id="q5-文件创建失败" tabindex="-1">Q5：文件创建失败？ <a class="header-anchor" href="#q5-文件创建失败" aria-label="Permalink to &quot;Q5：文件创建失败？&quot;">​</a></h2><ul><li>检查题目名称是否包含 Windows 不允许的字符：<code>\\ / : * ? &quot; &lt; &gt; |</code>。</li><li>检查 VSCode 是否已打开工作区文件夹。</li><li>检查磁盘是否有写入权限。</li></ul><h2 id="q6-数据会上传到云端吗" tabindex="-1">Q6：数据会上传到云端吗？ <a class="header-anchor" href="#q6-数据会上传到云端吗" aria-label="Permalink to &quot;Q6：数据会上传到云端吗？&quot;">​</a></h2><p>不会。所有数据都在你的电脑本地流转：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OJ 页面 → Edge 扩展 → 本地 WebSocket → VSCode 扩展 → 本地文件</span></span></code></pre></div><p>WebSocket 服务器绑定在 <code>127.0.0.1</code>，仅本机可访问。</p><h2 id="q7-vscode-每次都要按-f5-启动吗" tabindex="-1">Q7：VSCode 每次都要按 F5 启动吗？ <a class="header-anchor" href="#q7-vscode-每次都要按-f5-启动吗" aria-label="Permalink to &quot;Q7：VSCode 每次都要按 F5 启动吗？&quot;">​</a></h2><p>不需要。安装 <code>.vsix</code> 后，每次打开 VSCode 会自动激活扩展并启动服务器，无需手动启动。</p><h2 id="q8-edge-提示「此扩展程序可能不安全」怎么办" tabindex="-1">Q8：Edge 提示「此扩展程序可能不安全」怎么办？ <a class="header-anchor" href="#q8-edge-提示「此扩展程序可能不安全」怎么办" aria-label="Permalink to &quot;Q8：Edge 提示「此扩展程序可能不安全」怎么办？&quot;">​</a></h2><p>因为扩展没有上架 Edge 商店、未经官方签名，属于正常提示。点击「保留」或「仍要启用」即可继续使用。</p><h2 id="🐛-反馈与建议" tabindex="-1">🐛 反馈与建议 <a class="header-anchor" href="#🐛-反馈与建议" aria-label="Permalink to &quot;🐛 反馈与建议&quot;">​</a></h2><p>如果遇到问题或有功能建议，欢迎通过 GitHub Issues 反馈： <code>https://github.com/KBP27444/kbp27444.github.io/issues</code></p><p>反馈时请附上：</p><ul><li>操作系统版本</li><li>Edge / VSCode 版本</li><li>问题现象截图</li><li>VSCode 扩展 Service Worker 控制台日志（在 <code>edge://extensions/</code> 页面点击扩展的「Service Worker」链接）</li></ul>',22))])}const m=t(c,[["render",h]]);export{k as __pageData,m as default};
